1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	)
13	
14	const storeFileName = "shadow-store.json"
15	const storeFormat = 1
16	
17	// View 是设备影子当前状态的只读快照。
18	type View struct {
19		DeviceID string
20		// Version 是设备当前版本（登记时的初始版本，随有效上报更新）。
21		Version string
22		// Online 表示设备是否在线。新登记设备离线，有效上报置为在线。
23		Online bool
24		// Revision 是当前期望配置的修订号，从零开始，每次成功修改加一。
25		Revision uint64
26		// Desired 是期望配置的完整 JSON 对象。
27		Desired json.RawMessage
28		// Reported 是上报配置的完整 JSON 对象。
29		Reported json.RawMessage
30		// LastSeq 是最后接受的上报序号。
31		LastSeq uint64
32	}
33	
34	// AuditRecord 是一次成功修改期望配置的审计记录。
35	type AuditRecord struct {
36		DeviceID string
37		Operator string
38		Time     time.Time
39		// Revision 是本次修改产生的新修订号。
40		Revision uint64
41		// RequestID 是产生本次修改的批量请求标识；单设备修改为空。
42		RequestID string
43		// Before 是修改前的完整期望配置。
44		Before json.RawMessage
45		// After 是修改后的完整期望配置。
46		After json.RawMessage
47	}
48	
49	// deviceState 是单台设备的内部状态。
50	type deviceState struct {
51		Version        string
52		Online         bool
53		Revision       uint64
54		Desired        json.RawMessage
55		Reported       json.RawMessage
56		LastSeq        uint64
57		LastReportTime time.Time
58		// DiffSince 记录每条差异路径首次出现的时间。
59		DiffSince map[string]time.Time
60		Audit     []AuditRecord
61	}
62	
63	// refreshDiff 重新计算差异路径：已有路径保留原时间，新路径使用 t，消失的路径移除。
64	func (d *deviceState) refreshDiff(t time.Time) {
65		entries := computeDiff(d.Desired, d.Reported)
66		next := make(map[string]time.Time, len(entries))
67		for _, e := range entries {
68			if since, ok := d.DiffSince[e.Path]; ok {
69				next[e.Path] = since
70			} else {
71				next[e.Path] = t
72			}
73		}
74		d.DiffSince = next
75	}
76	
77	// Store 是本地设备影子存储，所有状态与审计记录保存在指定目录。
78	// Store 可安全并发使用。
79	type Store struct {
80		mu        sync.Mutex
81		dir       string
82		closed    bool
83		devices   map[string]*deviceState
84		versions  map[string]*versionState
85		campaigns map[string]*campaignState
86		batches   map[string]*batchRequestState
87	}
88	
89	// Open 打开（必要时创建）位于 dir 的本地影子存储。
90	// 已有内容损坏或格式不识别时返回 ErrCorruptStorage，不会按空数据覆盖。
91	func Open(dir string) (*Store, error) {
92		if err := os.MkdirAll(dir, 0o755); err != nil {
93			return nil, fmt.Errorf("shadow: create store dir: %w", err)
94		}
95		s := &Store{
96			dir:       dir,
97			devices:   map[string]*deviceState{},
98			versions:  map[string]*versionState{},
99			campaigns: map[string]*campaignState{},
100			batches:   map[string]*batchRequestState{},
101		}
102		data, err := os.ReadFile(s.filePath())
103		if errors.Is(err, fs.ErrNotExist) {
104			return s, nil
105		}
106		if err != nil {
107			return nil, fmt.Errorf("shadow: read store: %w", err)
108		}
109		if err := s.restore(data); err != nil {
110			return nil, err
111		}
112		return s, nil
113	}
114	
115	// Close 关闭存储。关闭后的操作返回 ErrClosed。
116	func (s *Store) Close() error {
117		s.mu.Lock()
118		defer s.mu.Unlock()
119		if s.closed {
120			return ErrClosed
121		}
122		s.closed = true
123		return nil
124	}
125	
126	// Register 登记一台模拟设备。设备标识和初始版本不能为空；
127	// 重复登记返回 ErrDeviceExists。新设备初始离线，双方配置均为空对象。
128	func (s *Store) Register(deviceID, version string) error {
129		s.mu.Lock()
130		defer s.mu.Unlock()
131		if err := s.checkOpen(); err != nil {
132			return err
133		}
134		if deviceID == "" {
135			return ErrInvalidDeviceID
136		}
137		if version == "" {
138			return ErrInvalidVersion
139		}
140		if _, ok := s.devices[deviceID]; ok {
141			return fmt.Errorf("%w: %s", ErrDeviceExists, deviceID)
142		}
143		return s.commit(func() error {
144			s.devices[deviceID] = &deviceState{
145				Version:   version,
146				Desired:   json.RawMessage(`{}`),
147				Reported:  json.RawMessage(`{}`),
148				DiffSince: map[string]time.Time{},
149			}
150			return nil
151		})
152	}
153	
154	// UpdateDesired 修改设备的期望配置，完整替换旧配置。
155	// 需携带操作者、操作时间和已读取的期望修订号；修订号不等于当前值时
156	// 返回 ErrRevisionConflict，影子和审计均不改变。成功时返回新修订号。
157	//
158	// 配置校验、修订号判断、配置替换、审计与差异时间更新与批量修改共用同一
159	// 实现（checkDesiredMeta/checkDesiredRevision/applyDesired），仅校验次序
160	// 与错误消息格式保持各自既有形式。
161	func (s *Store) UpdateDesired(deviceID, operator string, at time.Time, revision uint64, config json.RawMessage) (uint64, error) {
162		s.mu.Lock()
163		defer s.mu.Unlock()
164		if err := s.checkOpen(); err != nil {
165			return 0, err
166		}
167		d, err := s.lookup(deviceID)
168		if err != nil {
169			return 0, err
170		}
171		if err := checkDesiredMeta(operator, at); err != nil {
172			return 0, err
173		}
174		cfg, err := validateConfig(config)
175		if err != nil {
176			return 0, err
177		}
178		if err := checkDesiredRevision(d, deviceID, revision); err != nil {
179			return 0, desiredSingleError(err.(errDesiredRevision))
180		}
181		var newRevision uint64
182		err = s.commit(func() error {
183			newRevision = applyDesired(d, deviceID, operator, at, "", cfg)
184			return nil
185		})
186		if err != nil {
187			return 0, err
188		}
189		return newRevision, nil
190	}
191	
192	// Report 处理设备上报。需携带正整数序号、时间、非空当前版本和完整配置。
193	// 更大序号更新上报并标为在线；相同序号且版本、配置、时间相同视为重复，
194	// 成功返回但不改变状态；相同序号内容不同或更小序号返回错误。
195	//
196	// 校验、序号判断与影子写入规则与安装/回滚成功的附带上报共用同一实现
197	// （checkReport/applyReport），仅错误类别保持各自公开的哨兵不变。
198	func (s *Store) Report(deviceID string, seq uint64, at time.Time, version string, config json.RawMessage) error {
199		s.mu.Lock()
200		defer s.mu.Unlock()
201		if err := s.checkOpen(); err != nil {
202			return err
203		}
204		d, err := s.lookup(deviceID)
205		if err != nil {
206			return err
207		}
208		in := reportInput{DeviceID: deviceID, Seq: seq, At: at, Version: version, Config: config}
209		cfg, verdict, err := checkReport(d, in, "")
210		if err != nil {
211			return reportPlainError(err.(errBadReport))
212		}
213		if verdict == reportDuplicate {
214			// 重复上报：成功返回，不写入影子，也不触发持久化。
215			return nil
216		}
217		return s.commit(func() error {
218			applyReport(d, in, cfg, verdict, at)
219			return nil
220		})
221	}
222	
223	// SetOffline 将设备标为离线。只改变在线状态，保留版本及双方配置。
224	func (s *Store) SetOffline(deviceID string) error {
225		s.mu.Lock()
226		defer s.mu.Unlock()
227		if err := s.checkOpen(); err != nil {
228			return err
229		}
230		d, err := s.lookup(deviceID)
231		if err != nil {
232			return err
233		}
234		return s.commit(func() error {
235			d.Online = false
236			return nil
237		})
238	}
239	
240	// Get 返回设备影子当前状态的快照。返回的数据是独立副本，
241	// 调用方修改不影响已保存的记录。
242	func (s *Store) Get(deviceID string) (View, error) {
243		s.mu.Lock()
244		defer s.mu.Unlock()
245		if err := s.checkOpen(); err != nil {
246			return View{}, err
247		}
248		d, err := s.lookup(deviceID)
249		if err != nil {
250			return View{}, err
251		}
252		return View{
253			DeviceID: deviceID,
254			Version:  d.Version,
255			Online:   d.Online,
256			Revision: d.Revision,
257			Desired:  cloneRaw(d.Desired),
258			Reported: cloneRaw(d.Reported),
259			LastSeq:  d.LastSeq,
260		}, nil
261	}
262	
263	// Diff 返回期望配置与上报配置之间的差异，按 JSON Pointer 路径字典序排列。
264	func (s *Store) Diff(deviceID string) ([]DiffEntry, error) {
265		s.mu.Lock()
266		defer s.mu.Unlock()
267		if err := s.checkOpen(); err != nil {
268			return nil, err
269		}
270		d, err := s.lookup(deviceID)
271		if err != nil {
272			return nil, err
273		}
274		entries := computeDiff(d.Desired, d.Reported)
275		for i := range entries {
276			entries[i].Since = d.DiffSince[entries[i].Path]
277		}
278		return entries, nil
279	}
280	
281	// Audit 按修订号递增返回设备的审计记录。返回的数据是独立副本。
282	func (s *Store) Audit(deviceID string) ([]AuditRecord, error) {
283		s.mu.Lock()
284		defer s.mu.Unlock()
285		if err := s.checkOpen(); err != nil {
286			return nil, err
287		}
288		d, err := s.lookup(deviceID)
289		if err != nil {
290			return nil, err
291		}
292		out := make([]AuditRecord, len(d.Audit))
293		for i, rec := range d.Audit {
294			out[i] = rec
295			out[i].Before = cloneRaw(rec.Before)
296			out[i].After = cloneRaw(rec.After)
297		}
298		return out, nil
299	}
300	
301	func (s *Store) checkOpen() error {
302		if s.closed {
303			return ErrClosed
304		}
305		return nil
306	}
307	
308	func (s *Store) lookup(deviceID string) (*deviceState, error) {
309		if deviceID == "" {
310			return nil, ErrInvalidDeviceID
311		}
312		d, ok := s.devices[deviceID]
313		if !ok {
314			return nil, fmt.Errorf("%w: %s", ErrDeviceNotFound, deviceID)
315		}
316		return d, nil
317	}
318	
319	// commit 执行一次状态修改并持久化。保存失败时回滚内存状态并返回错误，
320	// 保证一次操作涉及的状态与审计一起保存、查询仍显示操作前的结果。
321	// 调用时必须持有 s.mu。
322	func (s *Store) commit(mutate func() error) error {
323		snapshot, err := s.marshal()
324		if err != nil {
325			return err
326		}
327		if err := mutate(); err != nil {
328			return err
329		}
330		if err := s.persist(); err != nil {
331			// 回滚内存状态；snapshot 由本进程序列化，恢复不应失败。
332			_ = s.restore(snapshot)
333			return err
334		}
335		return nil
336	}
337	
338	func (s *Store) filePath() string {
339		return filepath.Join(s.dir, storeFileName)
340	}
341	
342	// persist 把当前状态原子写入存储文件。
343	func (s *Store) persist() error {
344		data, err := s.marshal()
345		if err != nil {
346			return err
347		}
348		tmp, err := os.CreateTemp(s.dir, ".shadow-store-*.tmp")
349		if err != nil {
350			return fmt.Errorf("shadow: save store: %w", err)
351		}
352		tmpName := tmp.Name()
353		if _, err := tmp.Write(data); err != nil {
354			tmp.Close()
355			os.Remove(tmpName)
356			return fmt.Errorf("shadow: save store: %w", err)
357		}
358		if err := tmp.Sync(); err != nil {
359			tmp.Close()
360			os.Remove(tmpName)
361			return fmt.Errorf("shadow: save store: %w", err)
362		}
363		if err := tmp.Close(); err != nil {
364			os.Remove(tmpName)
365			return fmt.Errorf("shadow: save store: %w", err)
366		}
367		if err := os.Rename(tmpName, s.filePath()); err != nil {
368			os.Remove(tmpName)
369			return fmt.Errorf("shadow: save store: %w", err)
370		}
371		return nil
372	}
373	
374	// diskStore 是存储文件的磁盘格式。
375	type diskStore struct {
376		Format    int                     `json:"format"`
377		Devices   map[string]diskState    `json:"devices"`
378		Versions  map[string]diskVersion  `json:"versions,omitempty"`
379		Campaigns map[string]diskCampaign `json:"campaigns,omitempty"`
380		Batches   map[string]diskBatch    `json:"batches,omitempty"`
381	}
382	
383	type diskState struct {
384		Version        string               `json:"version"`
385		Online         bool                 `json:"online"`
386		Revision       uint64               `json:"revision"`
387		Desired        json.RawMessage      `json:"desired"`
388		Reported       json.RawMessage      `json:"reported"`
389		LastSeq        uint64               `json:"lastSeq"`
390		LastReportTime time.Time            `json:"lastReportTime,omitempty"`
391		DiffSince      map[string]time.Time `json:"diffSince,omitempty"`
392		Audit          []diskAudit          `json:"audit,omitempty"`
393	}
394	
395	type diskAudit struct {
396		Operator  string          `json:"operator"`
397		Time      time.Time       `json:"time"`
398		Revision  uint64          `json:"revision"`
399		RequestID string          `json:"requestId,omitempty"`
400		Before    json.RawMessage `json:"before"`
401		After     json.RawMessage `json:"after"`
402	}
403	
404	func (s *Store) marshal() ([]byte, error) {
405		disk := diskStore{Format: storeFormat, Devices: make(map[string]diskState, len(s.devices))}
406		for id, d := range s.devices {
407			ds := diskState{
408				Version:        d.Version,
409				Online:         d.Online,
410				Revision:       d.Revision,
411				Desired:        cloneRaw(d.Desired),
412				Reported:       cloneRaw(d.Reported),
413				LastSeq:        d.LastSeq,
414				LastReportTime: d.LastReportTime,
415				DiffSince:      make(map[string]time.Time, len(d.DiffSince)),
416			}
417			for p, t := range d.DiffSince {
418				ds.DiffSince[p] = t
419			}
420			for _, rec := range d.Audit {
421				ds.Audit = append(ds.Audit, diskAudit{
422					Operator:  rec.Operator,
423					Time:      rec.Time,
424					Revision:  rec.Revision,
425					RequestID: rec.RequestID,
426					Before:    cloneRaw(rec.Before),
427					After:     cloneRaw(rec.After),
428				})
429			}
430			disk.Devices[id] = ds
431		}
432		disk.Versions = s.marshalVersions()
433		campaigns, err := s.marshalCampaigns()
434		if err != nil {
435			return nil, err
436		}
437		disk.Campaigns = campaigns
438		disk.Batches = s.marshalBatches()
439		data, err := json.Marshal(disk)
440		if err != nil {
441			return nil, fmt.Errorf("shadow: encode store: %w", err)
442		}
443		return data, nil
444	}
445	
446	// restore 从存储文件内容恢复状态。内容损坏或格式不识别时返回
447	// ErrCorruptStorage，绝不按空数据覆盖。
448	func (s *Store) restore(data []byte) error {
449		var disk diskStore
450		if err := json.Unmarshal(data, &disk); err != nil {
451			return fmt.Errorf("%w: %v", ErrCorruptStorage, err)
452		}
453		if disk.Format != storeFormat {
454			return fmt.Errorf("%w: unsupported format %d", ErrCorruptStorage, disk.Format)
455		}
456		devices := make(map[string]*deviceState, len(disk.Devices))
457		for id, ds := range disk.Devices {
458			if id == "" {
459				return fmt.Errorf("%w: empty device id", ErrCorruptStorage)
460			}
461			if _, ok := decodeObject(ds.Desired); !ok {
462				return fmt.Errorf("%w: device %s desired config invalid", ErrCorruptStorage, id)
463			}
464			if _, ok := decodeObject(ds.Reported); !ok {
465				return fmt.Errorf("%w: device %s reported config invalid", ErrCorruptStorage, id)
466			}
467			d := &deviceState{
468				Version:        ds.Version,
469				Online:         ds.Online,
470				Revision:       ds.Revision,
471				Desired:        cloneRaw(ds.Desired),
472				Reported:       cloneRaw(ds.Reported),
473				LastSeq:        ds.LastSeq,
474				LastReportTime: ds.LastReportTime,
475				DiffSince:      make(map[string]time.Time, len(ds.DiffSince)),
476			}
477			for p, t := range ds.DiffSince {
478				d.DiffSince[p] = t
479			}
480			for _, da := range ds.Audit {
481				if da.Operator == "" || da.Time.IsZero() || da.Revision == 0 {
482					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
483				}
484				if _, ok := decodeObject(da.Before); !ok {
485					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
486				}
487				if _, ok := decodeObject(da.After); !ok {
488					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
489				}
490				d.Audit = append(d.Audit, AuditRecord{
491					DeviceID:  id,
492					Operator:  da.Operator,
493					Time:      da.Time,
494					Revision:  da.Revision,
495					RequestID: da.RequestID,
496					Before:    cloneRaw(da.Before),
497					After:     cloneRaw(da.After),
498				})
499			}
500			// 审计必须能完整解释当前期望配置：修订号从 1 开始逐条连续到当前
501			// 修订号；首条修改前是登记时的空对象，每条修改后等于下一条修改前，
502			// 末条修改后等于当前期望配置。比较沿用配置的 JSON 语义，不要求
503			// 操作时间严格递增。修订号为 0 时审计必须为空、期望必须为空对象。
504			if uint64(len(d.Audit)) != d.Revision {
505				return fmt.Errorf("%w: device %s audit history does not cover revision %d",
506					ErrCorruptStorage, id, d.Revision)
507			}
508			expected := json.RawMessage(`{}`)
509			for i, rec := range d.Audit {
510				if rec.Revision != uint64(i+1) {
511					return fmt.Errorf("%w: device %s audit revision %d out of sequence",
512						ErrCorruptStorage, id, rec.Revision)
513				}
514				if !rawEqual(rec.Before, expected) {
515					return fmt.Errorf("%w: device %s audit revision %d broken chain",
516						ErrCorruptStorage, id, rec.Revision)
517				}
518				expected = rec.After
519			}
520			if !rawEqual(expected, d.Desired) {
521				return fmt.Errorf("%w: device %s desired config not explained by audit",
522					ErrCorruptStorage, id)
523			}
524			// 差异计时记录必须与双方当前配置重新计算出的差异完全一致：
525			// 每条实际差异都要有一条非零的首次出现时间，记录中也不能残留
526			// 当前已经没有差异的路径（父路径不能代替子路径，路径不同即使
527			// 条数相同也不行）。没有差异时允许不保存记录或保存空记录。
528			entries := computeDiff(d.Desired, d.Reported)
529			if len(entries) != len(d.DiffSince) {
530				return fmt.Errorf("%w: device %s diff times do not match current diff paths",
531					ErrCorruptStorage, id)
532			}
533			for _, e := range entries {
534				since, ok := d.DiffSince[e.Path]
535				if !ok {
536					return fmt.Errorf("%w: device %s diff %s missing first-seen time",
537						ErrCorruptStorage, id, e.Path)
538				}
539				if since.IsZero() {
540					return fmt.Errorf("%w: device %s diff %s has zero first-seen time",
541						ErrCorruptStorage, id, e.Path)
542				}
543			}
544			devices[id] = d
545		}
546		s.devices = devices
547		if err := s.restoreVersions(disk.Versions); err != nil {
548			return err
549		}
550		if err := s.restoreCampaigns(disk.Campaigns); err != nil {
551			return err
552		}
553		if err := s.restoreBatches(disk.Batches); err != nil {
554			return err
555		}
556		return nil
557	}
558

