1	package shadow
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 活动已因超时结束（12:10）后，用原截止时间或更晚的时间领取是纯拒绝：
10	// 返回空操作和 ErrCampaignEnded，不推进用于判断时间倒退的记录。
11	// 随后 12:15 的 AdvanceCampaign 正常返回，12:15 的领取仍是活动已结束
12	// 而不是时间倒退；关闭重开后被拒绝的 12:20 也不应被保存下来。
13	func TestClaimAfterTimeoutEndIsPureReject(t *testing.T) {
14		s, dir := setupUpgradeDir(t, "d1")
15		spec := endedSpec([]string{"d1"}, 1, false)
16		createCampaign(t, s, spec)
17		bringOnline(t, s, "d1")
18		dl, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute)) // 12:02 已领取下载，未完成
19		if err != nil || dl == nil || dl.Kind != StageDownload {
20			t.Fatalf("claim download: %v %+v", err, dl)
21		}
22		end := upBase.Add(10 * time.Minute) // 12:10 截止并超时结束
23		if err := s.AdvanceCampaign(spec.ID, end); err != nil {
24			t.Fatal(err)
25		}
26		before, _ := s.GetCampaign(spec.ID)
27		if !before.Ended || !before.EndedAt.Equal(end) {
28			t.Fatalf("campaign not ended at deadline: %+v", before)
29		}
30		shadowBefore, _ := s.Get("d1")
31	
32		// 12:20 的领取：空操作 + ErrCampaignEnded，且是纯拒绝。
33		op, err := s.Claim(spec.ID, "d1", upBase.Add(20*time.Minute))
34		if !errors.Is(err, ErrCampaignEnded) || op != nil {
35			t.Fatalf("claim after end: op %+v err %v", op, err)
36		}
37		after, _ := s.GetCampaign(spec.ID)
38		if !after.Ended || after.Status != CampaignFailed || !after.EndedAt.Equal(end) {
39			t.Fatalf("campaign conclusion/end time changed: %+v", after)
40		}
41		d := findDevice(after, "d1")
42		if d.Status != DeviceTimeout || d.Phase != StageDownload ||
43			d.Reason == "" || !d.At.Equal(end) {
44			t.Fatalf("device state changed by rejected claim: %+v", d)
45		}
46		if len(after.Results) != len(before.Results) {
47			t.Fatalf("rejected claim added history: %d -> %d", len(before.Results), len(after.Results))
48		}
49		sh, _ := s.Get("d1")
50		if sh.Version != shadowBefore.Version || sh.Online != shadowBefore.Online ||
51			sh.Revision != shadowBefore.Revision || sh.LastSeq != shadowBefore.LastSeq ||
52			!rawEqual(sh.Desired, shadowBefore.Desired) || !rawEqual(sh.Reported, shadowBefore.Reported) {
53			t.Fatalf("shadow changed by rejected claim: before %+v after %+v", shadowBefore, sh)
54		}
55	
56		// 被拒绝的 12:20 不计入活动时间：12:15 推进正常，12:15 领取是活动已结束。
57		if err := s.AdvanceCampaign(spec.ID, upBase.Add(15*time.Minute)); err != nil {
58			t.Fatalf("advance after rejected claim must not regress: %v", err)
59		}
60		if _, err := s.Claim(spec.ID, "d1", upBase.Add(15*time.Minute)); !errors.Is(err, ErrCampaignEnded) {
61			t.Fatalf("claim at 12:15: %v", err)
62		}
63		// 早于真正已接受时间（12:10）仍判倒退，且不改变记录。
64		if _, err := s.Claim(spec.ID, "d1", upBase.Add(5*time.Minute)); !errors.Is(err, ErrTimeRegression) {
65			t.Fatalf("claim before accepted time: %v", err)
66		}
67		// 领取时间缺失仍返回 ErrInvalidTime。
68		if _, err := s.Claim(spec.ID, "d1", time.Time{}); !errors.Is(err, ErrInvalidTime) {
69			t.Fatalf("claim without time: %v", err)
70		}
71	
72		// 关闭重开后时间判断与拒绝领取前一致：被拒绝的 12:20 不能被保存下来。
73		if err := s.Close(); err != nil {
74			t.Fatal(err)
75		}
76		s2, err := Open(dir)
77		if err != nil {
78			t.Fatalf("reopen: %v", err)
79		}
80		defer s2.Close()
81		if err := s2.AdvanceCampaign(spec.ID, upBase.Add(15*time.Minute)); err != nil {
82			t.Fatalf("rejected claim time persisted across reopen: %v", err)
83		}
84		if _, err := s2.Claim(spec.ID, "d1", upBase.Add(15*time.Minute)); !errors.Is(err, ErrCampaignEnded) {
85			t.Fatalf("claim after reopen: %v", err)
86		}
87		cv, _ := s2.GetCampaign(spec.ID)
88		if !cv.Ended || !cv.EndedAt.Equal(end) || findDevice(cv, "d1").Status != DeviceTimeout {
89			t.Fatalf("reopen changed ended campaign: %+v", cv)
90		}
91	}
92	
93	// 截止前已成功结束的活动：无论领取时间在原截止前、恰好截止或截止后，
94	// 拒绝都不得改变活动结论、结束时间与时间基线。
95	func TestClaimAfterEarlySuccessIsPureReject(t *testing.T) {
96		s := setupUpgrade(t, "d1")
97		spec := upSpec()
98		spec.Devices = []string{"d1"}
99		spec.BatchSize = 1
100		createCampaign(t, s, spec)
101		bringOnline(t, s, "d1")
102		finishDevice(t, s, spec, "d1", upBase.Add(2*time.Minute)) // 12:05 成功结束
103		before, _ := s.GetCampaign(spec.ID)
104		if !before.Ended || before.Status != CampaignSucceeded {
105			t.Fatalf("campaign not succeeded early: %+v", before)
106		}
107		end := before.EndedAt
108	
109		for _, at := range []time.Time{
110			upBase.Add(30 * time.Minute), // 截止前
111			spec.Deadline,                // 恰好截止
112			spec.Deadline.Add(time.Hour), // 截止后
113		} {
114			op, err := s.Claim(spec.ID, "d1", at)
115			if !errors.Is(err, ErrCampaignEnded) || op != nil {
116				t.Fatalf("claim at %v: op %+v err %v", at, op, err)
117			}
118		}
119		after, _ := s.GetCampaign(spec.ID)
120		if !after.Ended || after.Status != CampaignSucceeded || !after.EndedAt.Equal(end) ||
121			len(after.Results) != len(before.Results) {
122			t.Fatalf("rejected claims changed campaign: %+v", after)
123		}
124		// 截止后的被拒绝领取不推进基线：截止前的合法时间仍不判倒退。
125		if err := s.AdvanceCampaign(spec.ID, upBase.Add(30*time.Minute)); err != nil {
126			t.Fatalf("rejected claim advanced time baseline: %v", err)
127		}
128	}
129	
130	// 截止前已失败结束的活动同样适用：截止后的领取是纯拒绝，不推进基线。
131	func TestClaimAfterEarlyFailureIsPureReject(t *testing.T) {
132		s := setupUpgrade(t, "d1")
133		spec := upSpec()
134		spec.Devices = []string{"d1"}
135		spec.BatchSize = 1
136		createCampaign(t, s, spec)
137		bringOnline(t, s, "d1")
138		dl, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
139		if err != nil || dl == nil {
140			t.Fatalf("claim download: %v %+v", err, dl)
141		}
142		if err := s.SubmitResult(OperationResult{
143			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
144			At: upBase.Add(3 * time.Minute), Success: false, Reason: "download broken",
145		}); err != nil {
146			t.Fatal(err)
147		}
148		before, _ := s.GetCampaign(spec.ID)
149		if !before.Ended || before.Status != CampaignFailed {
150			t.Fatalf("campaign not failed early: %+v", before)
151		}
152	
153		op, err := s.Claim(spec.ID, "d1", spec.Deadline.Add(time.Hour))
154		if !errors.Is(err, ErrCampaignEnded) || op != nil {
155			t.Fatalf("claim after failed campaign: op %+v err %v", op, err)
156		}
157		after, _ := s.GetCampaign(spec.ID)
158		if !after.Ended || after.Status != CampaignFailed || !after.EndedAt.Equal(before.EndedAt) ||
159			len(after.Results) != len(before.Results) {
160			t.Fatalf("rejected claim changed campaign: %+v", after)
161		}
162		if err := s.AdvanceCampaign(spec.ID, upBase.Add(30*time.Minute)); err != nil {
163			t.Fatalf("rejected claim advanced time baseline: %v", err)
164		}
165	}
166	
167	// 回滚已领取但未完成，活动超时结束后领取不能再返回该回滚操作；
168	// 等待回滚（未领取）的设备同样只能得到纯拒绝。
169	func TestClaimAfterEndReturnsNoRollbackOp(t *testing.T) {
170		s := setupUpgrade(t, "d1", "d2")
171		spec := endedSpec([]string{"d1", "d2"}, 2, true)
172		createCampaign(t, s, spec)
173		bringOnline(t, s, "d1")
174		bringOnline(t, s, "d2")
175		awaitRollback(t, s, spec, "d1", upBase.Add(1*time.Minute))
176		rb, err := s.Claim(spec.ID, "d1", upBase.Add(5*time.Minute)) // d1 正在回滚
177		if err != nil || rb == nil || rb.Kind != StageRollback {
178			t.Fatalf("claim rollback: %v %+v", err, rb)
179		}
180		awaitRollback(t, s, spec, "d2", upBase.Add(5*time.Minute)) // d2 等待回滚
181	
182		end := upBase.Add(10 * time.Minute)
183		if err := s.AdvanceCampaign(spec.ID, end); err != nil {
184			t.Fatal(err)
185		}
186		for _, id := range []string{"d1", "d2"} {
187			op, err := s.Claim(spec.ID, id, upBase.Add(20*time.Minute))
188			if !errors.Is(err, ErrCampaignEnded) || op != nil {
189				t.Fatalf("claim %s after end: op %+v err %v", id, op, err)
190			}
191		}
192		cv, _ := s.GetCampaign(spec.ID)
193		if findDevice(cv, "d1").Status != DeviceRollbackTimeout ||
194			findDevice(cv, "d2").Status != DeviceRollbackTimeout {
195			t.Fatalf("rejected claims changed rollback timeout state: %+v", cv)
196		}
197		// 纯拒绝不推进基线。
198		if err := s.AdvanceCampaign(spec.ID, upBase.Add(15*time.Minute)); err != nil {
199			t.Fatalf("rejected claim advanced time baseline: %v", err)
200		}
201		// 活动结束后设备查询也不再给出待办操作。
202		for _, id := range []string{"d1", "d2"} {
203			w, err := s.GetDeviceWork(id)
204			if err != nil {
205				t.Fatal(err)
206			}
207			if w.Pending != nil || w.CampaignID != "" {
208				t.Fatalf("device %s still has work after end: %+v", id, w)
209			}
210		}
211	}
212	
213	// 保留活动仍在执行时领取首次到达截止时间的原有功能：不派发操作，
214	// 全部未结束设备按阶段记为超时，已有终态保持不变，以本次领取时间结束活动；
215	// 即使领取的设备早已成功，其他未结束设备也必须被处理；此次结束时间参与倒退判断。
216	func TestFirstClaimAtDeadlineStillCascades(t *testing.T) {
217		s := setupUpgrade(t, "d1", "d2")
218		spec := endedSpec([]string{"d1", "d2"}, 1, false)
219		createCampaign(t, s, spec)
220		bringOnline(t, s, "d1")
221		bringOnline(t, s, "d2")
222		finishDevice(t, s, spec, "d1", upBase.Add(1*time.Minute)) // d1 已成功
223		dl2, err := s.Claim(spec.ID, "d2", upBase.Add(5*time.Minute))
224		if err != nil || dl2 == nil {
225			t.Fatalf("claim download d2: %v %+v", err, dl2)
226		}
227		end := upBase.Add(10 * time.Minute)
228		// 由早已成功的 d1 在截止时刻领取：仍要级联处理 d2。
229		op, err := s.Claim(spec.ID, "d1", end)
230		if !errors.Is(err, ErrCampaignEnded) || op != nil {
231			t.Fatalf("claim at deadline: op %+v err %v", op, err)
232		}
233		cv, _ := s.GetCampaign(spec.ID)
234		if !cv.Ended || cv.Status != CampaignFailed || !cv.EndedAt.Equal(end) {
235			t.Fatalf("deadline claim did not end campaign: %+v", cv)
236		}
237		if findDevice(cv, "d1").Status != DeviceSucceeded {
238			t.Fatalf("terminal device changed: %+v", findDevice(cv, "d1"))
239		}
240		d2 := findDevice(cv, "d2")
241		if d2.Status != DeviceTimeout || d2.Phase != StageDownload || !d2.At.Equal(end) {
242			t.Fatalf("unfinished device not timed out: %+v", d2)
243		}
244		// 此次结束时间参与倒退判断。
245		if err := s.AdvanceCampaign(spec.ID, upBase.Add(5*time.Minute)); !errors.Is(err, ErrTimeRegression) {
246			t.Fatalf("deadline claim time must join regression check: %v", err)
247		}
248		// 之后的领取是纯拒绝，不再推进基线。
249		if _, err := s.Claim(spec.ID, "d2", upBase.Add(20*time.Minute)); !errors.Is(err, ErrCampaignEnded) {
250			t.Fatalf("claim after deadline end: %v", err)
251		}
252		if err := s.AdvanceCampaign(spec.ID, upBase.Add(15*time.Minute)); err != nil {
253			t.Fatalf("rejected claim advanced time baseline: %v", err)
254		}
255	}
