			t.Fatal(err)
		}
		s.Close()
		original := setCampaignLastTime(t, dir, spec.ID, "2026-10-02T12:05:00Z")
		assertReopenCorrupt(t, dir, original)
	})

	// 活动无任何领取/结果/状态时间，仅由截止推进在 14:00 超时结束：
	// 基线 13:00 晚于创建时间，却早于保存的结束时间（以及超时状态时间），
	// 只能由结束时间/设备状态时间检查发现。
