531	// checkCampaignTimeBaseline 校验活动时间基线（已接受的最新时间）与保存的
532	// 业务记录自洽：基线必须不早于创建时间、任一设备已经领取下载/安装/回滚的
533	// 时间、任一操作首次接受结果的时间、设备当前状态中已记录的时间；活动已结束
534	// 时还必须不早于保存的结束时间。只比较确实存在的记录：尚未领取的操作没有
535	// 领取时间、尚未接受结果的操作没有结果时间、新建且尚未推进的设备允许没有
536	// 状态时间，这些正常缺省值不导致打开失败。比较按绝对时刻进行，相等合法。
537	func checkCampaignTimeBaseline(campaignID string, c *campaignState) error {
538		baseline := c.LastTime
539		bad := func(format string, args ...any) error {
540			msg := fmt.Sprintf(format, args...)
541			return fmt.Errorf("%w: campaign %s time baseline %s %s",
542				ErrCorruptStorage, campaignID, baseline.Format(time.RFC3339Nano), msg)
543		}
544		if baseline.Before(c.CreatedAt) {
545			return bad("before creation time %s", c.CreatedAt.Format(time.RFC3339Nano))
546		}
547		if c.Ended && !c.EndedAt.IsZero() && baseline.Before(c.EndedAt) {
548			return bad("before end time %s", c.EndedAt.Format(time.RFC3339Nano))
549		}
550		for _, cd := range c.Devices {
551			if !cd.At.IsZero() && baseline.Before(cd.At) {
552				return bad("before device %s state time %s",
553					cd.DeviceID, cd.At.Format(time.RFC3339Nano))
554			}
555			// 已领取（含尚未完成）的操作一定接受过携带领取时刻的请求；
556			// 已接受结果的操作还必须比较首次接受结果的时间。未领取/未接受
557			// 的操作对应时间为零值，属正常缺省，跳过比较。
558			ops := []struct {
559				stage string
560				op    *opState
561			}{
562				{StageDownload, &cd.Download},
563				{StageInstall, &cd.Install},
564				{StageRollback, &cd.Rollback},
565			}
566			for _, item := range ops {
567				if !item.op.ClaimedAt.IsZero() && baseline.Before(item.op.ClaimedAt) {
568					return bad("before device %s %s claim time %s",
569						cd.DeviceID, item.stage, item.op.ClaimedAt.Format(time.RFC3339Nano))
570				}
571				if item.op.HasResult && !item.op.At.IsZero() && baseline.Before(item.op.At) {
572					return bad("before device %s %s result time %s",
573						cd.DeviceID, item.stage, item.op.At.Format(time.RFC3339Nano))
574				}
575			}
576		}
577		return nil
578	}
579	
580	func validDeviceStatus(status string) bool {
581		switch status {
582		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
583			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
584			DeviceAwaitingRollback, DeviceRollingBack,
585			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
586			return true
587		default:
588			return false

